  "adm.drive.title": "Google Drive video",
  "adm.drive.how": "Students watch this video inside the class page — no Google sign-in, no “You need permission”. For that, share the video with the website’s own Google address:",
  "adm.drive.email": "Share the video with this address",
  "adm.drive.copy": "Copy",
  "adm.drive.copied": "Copied.",
  "adm.drive.steps": "In Google Drive: right-click the video (or the folder that holds all your class videos) → Share → paste this address → choose “Viewer” → Send. Sharing the folder once covers every video in it.",
  "adm.drive.noDownload": "If the video has “Disable options to download, print, and copy for commenters and viewers” switched on, Google will not give it to a Viewer: choose “Editor” instead, or switch that option off.",
