  "adm.drive.noKeyBody": "Until then, students see “This class video is being prepared” instead of the video. Add the Google key as the GitHub secret GOOGLE_SERVICE_ACCOUNT (the same one Analytics uses — see Analytics → how to set it up), then run Deploy again.",
