  "adm.an.conn.last": "Last answer from Google",
  "adm.an.conn.lastOk": "Fine ({when})",
  "adm.an.conn.lastFail": "A problem ({when})",
  "adm.an.conn.lastNever": "Not asked yet",
  "adm.an.conn.check": "Check the connection",
  "adm.an.conn.ok": "Connected — Google answered.",
  "adm.an.conn.readonly": "Only the owner can press this.",
  "adm.an.said": "Google said",
  "adm.an.steps.title": "How to connect (once, about ten minutes)",
  "adm.an.steps.1": "In Google Cloud (console.cloud.google.com) choose or create a project, open APIs & Services → Library, find “Google Analytics Data API” and press Enable.",
  "adm.an.steps.2": "In the same project open IAM & Admin → Service accounts → Create service account (any name; no roles are needed). Open it → Keys → Add key → Create new key → JSON. A file downloads. That file is like a password: keep it private and never send it in a chat or an e-mail.",
  "adm.an.steps.3": "In Google Analytics open Admin → Property access management → + → Add users. Type the service account’s e-mail address (it ends with .iam.gserviceaccount.com), choose the role Viewer, and save.",
  "adm.an.steps.4": "On GitHub open the project → Settings → Secrets and variables → Actions → New repository secret. Name it GOOGLE_SERVICE_ACCOUNT and paste the whole content of the file. Then open Actions → Deploy → Run workflow. (Or, in Cloudflare, add a secret with the same name to the Worker.)",
  "adm.an.steps.5": "Come back here and press “Check the connection”. The first numbers appear within a minute; Google may need an hour or two to show the first visitors of a new tag.",
  "adm.an.outbound": "One setting in Google Analytics keeps private links private: open Admin → Data streams → your website stream → Enhanced measurement (the gear) and switch “Outbound clicks” off. Otherwise the addresses of live-class, group and lesson links, which are for enrolled students only, would be sent to Google when a student presses them.",
  "adm.an.p.not_configured.title": "Google is not connected yet",
  "adm.an.p.not_configured.body": "Admin can show your visitor numbers as soon as the website has the Google key file. Follow the steps below — once, about ten minutes.",
  "adm.an.p.key_invalid.title": "The key file cannot be read",
  "adm.an.p.key_invalid.body": "The secret GOOGLE_SERVICE_ACCOUNT is set, but it is not a Google key file (or it was cut off when it was pasted). Open the JSON file you downloaded from Google Cloud, copy everything from the first { to the last }, and save it again as a Secret (a plain or JSON variable typed into the Cloudflare dashboard is removed by the next deploy). Do not add quotes or change anything inside.",
  "adm.an.p.key_rejected.title": "Google did not accept the key",
  "adm.an.p.key_rejected.body": "The key may have been deleted or switched off in Google Cloud, or it belongs to another account. Make a new key (Service accounts → your account → Keys → Add key → JSON), save it as the secret GOOGLE_SERVICE_ACCOUNT, run Deploy, and check again.",
  "adm.an.p.api_disabled.title": "The Analytics Data API is switched off",
  "adm.an.p.api_disabled.body": "In your Google Cloud project open APIs & Services → Library, search for “Google Analytics Data API” and press Enable. Wait a minute, then check again. Google’s own words below include a direct link.",
  "adm.an.p.no_access.title": "The account cannot see your Analytics yet",
  "adm.an.p.no_access.body": "In Google Analytics open Admin → Property access management → + → Add users. Type {email}, choose the role Viewer, and save — in the property {property}, not another one. Then check again.",
  "adm.an.p.property_missing.title": "Google could not find the property",
  "adm.an.p.property_missing.body": "The property number {property} does not exist or is not a Google Analytics 4 property. In Google Analytics open Admin → Property details to see the right number, and ask your developer to change GA_PROPERTY_ID.",
  "adm.an.p.bad_request.title": "Google did not understand one of our questions",
  "adm.an.p.bad_request.body": "This is a problem in the website, not in your setup. Please show your developer the line “Google said” below.",
  "adm.an.p.quota.title": "Too many questions for now",
  "adm.an.p.quota.body": "Google limits how often the numbers can be asked for. Wait an hour and try again. The page keeps its answers for ten minutes, so this should not happen often.",
  "adm.an.p.network.title": "Google could not be reached",
  "adm.an.p.network.body": "The website could not connect to Google just now. Try again in a minute.",
  "adm.an.p.google_error.title": "Google had a problem",
  "adm.an.p.google_error.body": "Google answered with an error of its own. Try again later.",
  "adm.an.p.other.title": "Something went wrong",
  "adm.an.p.other.body": "Google gave an answer we did not expect. Check the connection again; if it keeps happening, show the line “Google said” to your developer.",
