  "adm.email.p.key_missing.title": "The website has no e-mail key yet",
  "adm.email.p.key_missing.body": "Create a key at resend.com → API Keys (permission: “Sending access”), then give it to the website as the secret RESEND_API_KEY: in the Cloudflare dashboard → Workers & Pages → academy-mawahbd-com → Settings → Variables and Secrets → Add. (Or add it as the GitHub repository secret RESEND_API_KEY and run Deploy.)",
  "adm.email.p.key_invalid.title": "Resend did not accept the key",
  "adm.email.p.key_invalid.body": "The key may have been deleted, mistyped or replaced. Create a new key at resend.com → API Keys (permission: “Sending access”) and save it over the secret RESEND_API_KEY in Cloudflare (Settings → Variables and Secrets → Edit).",
  "adm.email.p.key_restricted.title": "This key may not send e-mail",
  "adm.email.p.key_restricted.body": "Create a new key with the permission “Sending access” at resend.com → API Keys and save it over the secret RESEND_API_KEY in Cloudflare.",
  "adm.email.p.domain_not_verified.title": "Resend does not know {domain} yet",
  "adm.email.p.domain_not_verified.body": "E-mail can only be sent from a domain you have verified at Resend. At resend.com → Domains press Add Domain and enter {domain}. Copy the DNS records Resend shows into Cloudflare → DNS for {domain} (set each one to “DNS only”), then press Verify in Resend — usually a few minutes.",
  "adm.email.p.from_invalid.title": "The sender address is not valid",
  "adm.email.p.from_invalid.body": "MAIL_FROM in worker/wrangler.toml must look like: Name <name@yourdomain.com>. Right now it is: {from}",
  "adm.email.p.rate_limited.title": "Resend's sending limit has been reached",
  "adm.email.p.rate_limited.body": "Try again later (a free Resend plan has a daily and a monthly limit), or upgrade the Resend plan.",
  "adm.email.p.provider_error.title": "Resend had a problem on its side",
  "adm.email.p.provider_error.body": "Try again in a few minutes. You can check status.resend.com.",
  "adm.email.p.network.title": "The website could not reach Resend",
  "adm.email.p.network.body": "Try again in a minute.",
  "adm.email.p.other.title": "Resend refused the message",
  "adm.email.p.other.body": "Read what Resend says below and fix what it names.",
  "adm.email.replyTo": "Replies go to",
  "adm.email.sandboxTitle": "Your own notes arrive — but e-mails to students do not, yet",
  "adm.email.sandboxBody": "Resend has not verified {domain} yet, so it refuses e-mails to students (receipts, password links). Your own notifications still reach you, through Resend’s test sender. To fix it: at resend.com → Domains open {domain} and put the DNS records it shows into Cloudflare → DNS for {domain} (each one “DNS only”). After that Resend verifies by itself, within minutes to a few hours; press the test button again to see the warning go.",
  "adm.email.sentSandbox": "It arrived — through Resend’s test sender",
  "adm.email.sentSandboxBody": "Look in your inbox ({email}). The message went through Resend’s test sender because {domain} is not verified yet — so e-mails to students will still be refused until the DNS records are in place.",
