  "adm.pay.sslLogo": "SSLCommerz logo",
  "adm.pay.sslLogoHint": "SSLCommerz asks every shop to show its logo. Paste the link SSLCommerz gave you (or the whole code they sent) and press Save: their picture then shows on the online-payment choice at checkout and at the bottom of every page, in place of the small logos. Leave it empty and nothing of SSLCommerz’s is shown.",
