  "adm.drive.p.key_invalid.body": "সিক্রেট GOOGLE_SERVICE_ACCOUNT কোনো সার্ভিস-অ্যাকাউন্ট কী ফাইল নয়, অথবা মাঝখানে কাটা পড়েছে। পুরো JSON ফাইলটি আবার ওই সিক্রেটে সেভ করে Deploy চালান।",
  "adm.drive.p.key_rejected.title": "গুগল কী-টি মানেনি",
  "adm.drive.p.key_rejected.body": "কী-টি গুগল ক্লাউডে মুছে ফেলা বা বন্ধ করা হয়েছে, অথবা অন্য অ্যাকাউন্টের। সার্ভিস অ্যাকাউন্টের জন্য নতুন কী বানিয়ে GOOGLE_SERVICE_ACCOUNT-এ সেভ করুন এবং Deploy চালান।",
  "adm.drive.p.api_disabled.title": "আপনার গুগল প্রজেক্টে গুগল ড্রাইভ বন্ধ আছে",
  "adm.drive.p.api_disabled.body": "গুগল ক্লাউডে, সার্ভিস অ্যাকাউন্টের প্রজেক্টে APIs & Services → Library → Google Drive API → Enable চাপুন। এক মিনিট অপেক্ষা করে আবার পরীক্ষা করুন।",
  "adm.drive.p.not_drive_file.title": "এটি গুগল ড্রাইভের কোনো ফাইলের লিংক নয়",
  "adm.drive.p.not_drive_file.body": "ভিডিওর নিজস্ব লিংক বসান: ড্রাইভে ভিডিওতে রাইট-ক্লিক → Share → Copy link। (ইউটিউব ও ভিমিও লিংকে কিছু সেট করতে হয় না।)",
