  "adm.drive.p.no_access.title": "ওয়েবসাইট এই ফাইলটি দেখতে পাচ্ছে না",
  "adm.drive.p.no_access.body": "হয় ভিডিওটি ওয়েবসাইটের গুগল ঠিকানার সাথে এখনো শেয়ার করা হয়নি — উপরের ঠিকানায় “Viewer” হিসেবে শেয়ার করুন — অথবা লিংকটি ভুল। তারপর আবার পরীক্ষা করুন।",
