  "adm.drive.p.not_downloadable.body": "ভিডিওতে “Disable options to download, print, and copy for commenters and viewers” চালু আছে। সেটি বন্ধ করুন (ড্রাইভ → Share → গিয়ার আইকন), অথবা ভিডিওটি ওয়েবসাইটের ঠিকানার সাথে “Editor” হিসেবে শেয়ার করুন। তারপর আবার পরীক্ষা করুন।",
  "adm.drive.p.quota.title": "গুগল আপাতত এই ফাইলে সীমা বসিয়েছে",
  "adm.drive.p.quota.body": "গুগল একটি ফাইল দিনে নির্দিষ্ট পরিমাণই ডাউনলোড করতে দেয়, অথবা একসাথে অনেকে দেখছেন। এটি নিজে থেকেই ঠিক হয়, সাধারণত এক দিনের মধ্যে। একসাথে অনেক শিক্ষার্থীর জন্য ভিডিও Cloudflare Stream-এ রাখাই ঠিক।",
