  "adm.an.late": "Google-এর সংখ্যা এক দিন পর্যন্ত পিছিয়ে থাকতে পারে (বেশিরভাগ কয়েক ঘণ্টার মধ্যেই তৈরি হয়)। যাঁরা গোনায় না বলেছেন এবং কিছু অ্যাড-ব্লকার ব্যবহারকারী গোনা হন না, তাই প্রকৃত ভিজিটর একটু বেশি। নির্ভুল বিক্রির জন্য রিপোর্ট → আয় দেখুন।",
