  "adm.email.sandboxBody": "Resend এখনো {domain} যাচাই করেনি, তাই শিক্ষার্থীদের ইমেইল (রসিদ, পাসওয়ার্ড লিংক) ফিরিয়ে দিচ্ছে। আপনার নিজের নোটিফিকেশন তবু Resend-এর টেস্ট সেন্ডার দিয়ে আপনার কাছে আসছে। ঠিক করতে: resend.com → Domains-এ {domain} খুলে সেখানে দেখানো DNS রেকর্ডগুলো ক্লাউডফ্লেয়ার → {domain}-এর DNS-এ বসান (প্রতিটি “DNS only”)। এরপর কয়েক মিনিট থেকে কয়েক ঘণ্টার মধ্যে Resend নিজেই যাচাই করে নেয়; পরীক্ষার বোতাম আবার চাপলে সতর্কতা সরে যাবে।",
