  "adm.pay.sslLogoHint": "SSLCommerz প্রতিটি দোকানকে তাদের লোগো দেখাতে বলে। SSLCommerz যে লিংক (বা পুরো কোড) দিয়েছে সেটি এখানে বসিয়ে “সংরক্ষণ করুন” চাপুন: তখন তাদের ছবিটি চেকআউটে অনলাইন পেমেন্টের অপশনে আর প্রতিটি পাতার একদম নিচে দেখাবে, ছোট লোগোগুলোর জায়গায়। খালি রাখলে SSLCommerz-এর কিছুই দেখাবে না।",
  "adm.pay.link": "SSLCommerz পেমেন্ট লিংক (ঐচ্ছিক)",
  "adm.pay.linkHint": "আপনার SSLCommerz প্যানেলের পেমেন্ট লিংক (শুরু হয় https://invoice.sslcommerz.com/… দিয়ে)। লিংকটি এখানে থাকলে শিক্ষার্থীরা ম্যানুয়াল পেমেন্টে “কার্ড বা মোবাইল ব্যাংকিং (SSLCommerz-এর পেমেন্ট পেজ)” অপশনও দেখবে: সেই পেজে পেমেন্ট করে ট্রানজ্যাকশন আইডি দেবে, আর আপনি SSLCommerz প্যানেলে পেমেন্টটি মিলিয়ে এখানে অর্ডারটি অনুমোদন করবেন। এটি না চাইলে খালি রাখুন।",
