  "adm.pay.p.not_configured.body": "SSLCommerz মার্চেন্ট প্যানেল থেকে দুটি সিক্রেট ওয়েবসাইটে দিন — SSLCOMMERZ_STORE_ID ও SSLCOMMERZ_STORE_PASSWORD — GitHub সিক্রেট হিসেবে (রিপোজিটরি → Settings → Secrets and variables → Actions)। তারপর আবার Deploy চালান।",
  "adm.pay.p.credentials.title": "SSLCommerz স্টোরের কী মানছে না",
  "adm.pay.p.credentials.body": "সাধারণত এর একটি: (১) কী-গুলো টেস্ট (স্যান্ডবক্স) কিন্তু ওয়েবসাইট লাইভ মোডে — বা উল্টোটা; (২) লাইভ স্টোর SSLCommerz এখনো চালু করেনি; (৩) কী বদলে গেছে — যেমন মার্চেন্ট পাসওয়ার্ড বদলানোর পর। মার্চেন্ট প্যানেল থেকে স্টোর আইডি ও স্টোর পাসওয়ার্ড আবার কপি করুন (লাইভ মোডের জন্য লাইভগুলো), আগে-পরে কোনো ফাঁকা ছাড়া GitHub সিক্রেট SSLCOMMERZ_STORE_ID ও SSLCOMMERZ_STORE_PASSWORD-এ বসান, Deploy চালান, তারপর আবার পরীক্ষা করুন।",
  "adm.pay.p.domain.title": "SSLCommerz এই ওয়েবসাইটের ঠিকানা অনুমোদন করছে না",
  "adm.pay.p.domain.body": "মনে হচ্ছে স্টোরটি অন্য ওয়েবসাইটের নামে নিবন্ধিত। SSLCommerz-কে (মার্চেন্ট প্যানেলের সাপোর্ট, বা যিনি আপনাকে চালু করে দিয়েছেন) বলুন আপনার স্টোরে এই ওয়েবসাইট যোগ করতে এবং উপরের ফেরার ঠিকানাগুলো অনুমোদন করতে। সাধারণত একই অ্যাকাউন্টই থাকে। তারপর আবার পরীক্ষা করুন।",
  "adm.pay.p.blocked.title": "SSLCommerz ওয়েবসাইটের সার্ভারকে ফিরিয়ে দিয়েছে",
  "adm.pay.p.blocked.body": "SSLCommerz-এর ফায়ারওয়াল অনুরোধটি ফিরিয়ে দিয়েছে। কিছু স্টোর শুধু অনুমোদিত সার্ভার ঠিকানার তালিকা থেকে অনুরোধ নেয়; এই ওয়েবসাইট Cloudflare-এ চলে, যার ঠিকানা বদলায়, তাই তালিকায় রাখা যায় না। SSLCommerz সাপোর্টকে লিখুন: “আমাদের ওয়েবসাইট mawahacademy.com Cloudflare Workers-এ চলে। অনুগ্রহ করে আমাদের লাইভ স্টোরের IP বাধা তুলে দিন” — এবং নিচের কথাগুলো তাদের পাঠান।",
  "adm.pay.p.amount_limit.title": "SSLCommerz স্টোরের জন্য এত টাকার পেমেন্ট অনুমোদন করে না",
  "adm.pay.p.amount_limit.body": "সংযোগ ঠিক আছে, কিন্তু আপনার স্টোরের জন্য SSLCommerz-এর নিজস্ব সেটিংসে একবারে কত টাকা নেওয়া যাবে তার সীমা আছে, তাই আসল দামগুলো তারা ফিরিয়ে দিচ্ছে (তাদের কথা: “Transaction amount is not allowed as per admin configuration”)। ওয়েবসাইট, এর ডিজাইন বা অর্ডারের তথ্য এর কারণ নয়, আর এটা শুধু SSLCommerz-ই বদলাতে পারে। নিচের বার্তাটি SSLCommerz-কে পাঠান (মার্চেন্ট প্যানেল → সাপোর্ট, অথবা আপনার SSLCommerz যোগাযোগ)। তারা না বদলানো পর্যন্ত শিক্ষার্থীদের পেমেন্টের আগেই জানানো হয়, আর তারা “ম্যানুয়ালি সেন্ড মানি” দিয়ে পেমেন্ট করতে পারেন।",
  "adm.pay.chk.limited": "সংযোগ ঠিক আছে — কিন্তু SSLCommerz {amount}-এর পেমেন্ট ফিরিয়ে দিচ্ছে",
  "adm.pay.chk.capNow": "SSLCommerz {amount} বা তার বেশি পরিমাণের পেমেন্ট ফিরিয়ে দিয়েছে · {when}",
  "adm.pay.chk.msg": "SSLCommerz-কে পাঠানোর মতো একটি বার্তা (ইংরেজিতে)",
  "adm.pay.chk.msgText": "Dear SSLCommerz Support, our live store for the website {site} is connected, but every payment of {amount} or more is refused with the message “Transaction amount is not allowed as per admin configuration!”. A payment of 10 taka works. Our prices go up to {top}. Please remove the limit on the amount of one transaction for our store, or raise it to at least {top}. Thank you.",
